import { loadFont as loadPlexMono } from "@remotion/google-fonts/IBMPlexMono";
import React, { forwardRef, useEffect, useImperativeHandle, useMemo, useRef, useState, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, continueRender, delayRender, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

// Every timing in remocn is written in frames of a 30 fps timeline: a delay
// of 12, a rise over 20, a spring fed `fps`. Read straight from Remotion,
// those numbers mean something else in a 60 fps composition: a tween runs
// twice as fast, while a spring keeps its length, so a scene does not even
// speed up evenly.
//
// These two hooks stand in for Remotion's and answer on that 30 fps timeline
// whatever rate the composition runs at. At 60 fps the frame goes 0, 0.5, 1,
// 1.5: the scene lasts the same number of seconds and every frame in between
// is a new picture. At 30 fps they return exactly what Remotion does.
//
//   const frame = useSceneFrame();
//   const { fps, width } = useSceneConfig();
//
// What a component hands back to Remotion is still counted in the
// composition's own frames: `from` and `durationInFrames` of a `<Sequence>`,
// the length of a transition. `useCompositionFrames()` converts those.

/** The frame rate remocn timings are written in. */
const SCENE_FPS = 30;

/** `useCurrentFrame()` in 30 fps frames; fractional above 30 fps. */
function useSceneFrame(): number {
  const { fps } = useVideoConfig();
  return (useCurrentFrame() * SCENE_FPS) / fps;
}

/**
 * `useVideoConfig()` on the 30 fps timeline: `fps` is 30 and
 * `durationInFrames` counts 30 fps frames. Size and the rest are untouched.
 */
function useSceneConfig(): ReturnType<typeof useVideoConfig> {
  const config = useVideoConfig();
  return useMemo(
    () => ({
      ...config,
      fps: SCENE_FPS,
      durationInFrames: (config.durationInFrames * SCENE_FPS) / config.fps,
    }),
    [config],
  );
}

/**
 * Turns a count of 30 fps frames into the composition's own, for what
 * Remotion itself reads: `<Sequence from={frames(24)}>`. Whole frames only,
 * as Remotion requires.
 */
function useCompositionFrames(): (sceneFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (sceneFrames: number) => Math.round((sceneFrames * fps) / SCENE_FPS),
    [fps],
  );
}

/**
 * The other way round: a count Remotion gives a component in the
 * composition's own frames, in 30 fps frames. A transition's presentation
 * gets its length that way (`presentationDurationInFrames`).
 */
function useSceneFrameCount(): (compositionFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (compositionFrames: number) => (compositionFrames * SCENE_FPS) / fps,
    [fps],
  );
}

// A component's schedule, kept apart from its drawing: which elements the
// animation has (an entry, a word, a finale), when each starts and how long
// it runs. The schedule is a pure function of the props, so it can be read
// without rendering anything, and a `timing` prop can move, trim or stretch
// single elements without touching the code that draws them.
//
//   // timeline.ts, next to the component
//   export const titleTimeline = defineTimeline<TitleElementId, TitleProps>(
//     ({ words = WORDS }, { length }) =>
//       words.map((word, k) => ({
//         id: `word:${k}`,
//         lane: "Words",
//         label: word,
//         start: k * 8,
//         length: 8,
//         follows: k > 0 ? `word:${k - 1}` : undefined,
//         beats: { rise: 12 },
//       })),
//   );
//
//   // index.tsx
//   const tl = useTimeline(titleTimeline, props, length, timing);
//   const word = tl.get("word:0");
//   interpolate(t, [word.start, word.start + word.beat("rise")], [0, 1]);
//
// Every number is in frames of the 30 fps scene timeline, after `delay` and
// `speed`: those still apply to the whole animation, `timing` works inside it.
// Element ids are public API: a saved `timing` refers to them, so an id once
// shipped keeps its meaning.

/** One timed part of an animation, as its schedule lays it out. */
interface TimelineElement<Id extends string = string> {
  /** Stable name a `timing` override refers to: `entry:0`, `finale`. */
  id: Id;
  /** Row the element sits on in a timeline view. */
  lane: string;
  /** What the element shows, for people reading the timeline. */
  label: string;
  /** First frame of the element. */
  start: number;
  /** Frames until the next element of the lane takes over, or the end. */
  length: number;
  /**
   * The element this one comes after. When that element's end moves, this
   * one moves with it, keeping the gap between them.
   */
  follows?: Id;
  /**
   * Named frame counts inside the element, measured from its start: how long
   * a roll takes, when a second part begins. `stretch` scales them.
   */
  beats?: Record<string, number>;
}

/** A change to one element, made from outside the component. */
interface TimingOverride {
  /** New first frame. Wins over the shift from `follows`. */
  start?: number;
  /** New length, trimming or extending the element. Wins over `stretch`. */
  length?: number;
  /** Multiplies the length and every beat: 2 plays the element half as fast. */
  stretch?: number;
  /** Stops following: the element keeps its own start when the one before moves. */
  detach?: boolean;
}

/** Overrides by element id: the `timing` prop of a component. */
type Timing<Id extends string = string> = Partial<
  Record<Id, TimingOverride>
>;

/** A component's schedule: props and the scene length in, elements out. */
type Schedule<Id extends string, Props> = (
  props: Props,
  scene: { length: number },
) => TimelineElement<Id>[];

/** An element after `timing` has been applied. */
interface ResolvedElement<Id extends string = string>
  extends TimelineElement<Id> {
  /** `start + length`. */
  end: number;
  beats: Record<string, number>;
  /** A beat by name, stretched. Throws on a name the schedule didn't set. */
  beat(name: string): number;
  /**
   * 0 → 1 over the element, or over its first `beat` frames when a beat is
   * named. Clamped on both sides.
   */
  progress(frame: number, beat?: string): number;
}

interface ResolvedTimeline<Id extends string = string> {
  /** All elements, in the order the schedule returned them. */
  elements: ResolvedElement<Id>[];
  /** An element by id. Throws on an id the schedule didn't return. */
  get(id: Id): ResolvedElement<Id>;
  /** The elements of one lane, in order. */
  lane(name: string): ResolvedElement<Id>[];
}

/** Declares a schedule. Elements come back in time order. */
function defineTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
): Schedule<Id, Props> {
  return schedule;
}

/** Applies `timing` to a schedule's elements and carries the `follows` chains. */
function resolve<Id extends string>(
  elements: TimelineElement<Id>[],
  timing: Timing<Id> = {},
): ResolvedTimeline<Id> {
  const byId = new Map<Id, TimelineElement<Id>>(elements.map((e) => [e.id, e]));
  const done = new Map<Id, ResolvedElement<Id>>();
  const visiting = new Set<Id>();

  const place = (element: TimelineElement<Id>): ResolvedElement<Id> => {
    const known = done.get(element.id);
    if (known) return known;
    if (visiting.has(element.id)) {
      throw new Error(`timeline: "${element.id}" follows itself`);
    }
    visiting.add(element.id);

    const override: TimingOverride = timing[element.id] ?? {};
    const stretch = override.stretch ?? 1;
    const beats: Record<string, number> = {};
    for (const [name, frames] of Object.entries(element.beats ?? {})) {
      beats[name] = frames * stretch;
    }

    let start = element.start;
    const leader = element.follows ? byId.get(element.follows) : undefined;
    if (leader && !override.detach) {
      // The leader's end moved by this much; this element moves as far.
      start += place(leader).end - (leader.start + leader.length);
    }
    if (override.start !== undefined) start = override.start;
    const length = override.length ?? element.length * stretch;

    const beat = (name: string) => {
      const frames = beats[name];
      if (frames === undefined) {
        throw new Error(`timeline: "${element.id}" has no beat "${name}"`);
      }
      return frames;
    };
    const resolved: ResolvedElement<Id> = {
      ...element,
      start,
      length,
      end: start + length,
      beats,
      beat,
      progress: (frame, name) => {
        const span = name === undefined ? length : beat(name);
        if (span <= 0) return frame >= start ? 1 : 0;
        return Math.min(1, Math.max(0, (frame - start) / span));
      },
    };
    visiting.delete(element.id);
    done.set(element.id, resolved);
    return resolved;
  };

  const all = elements.map(place);
  return {
    elements: all,
    get: (id) => {
      const element = done.get(id);
      if (!element) throw new Error(`timeline: no element "${id}"`);
      return element;
    },
    lane: (name) => all.filter((e) => e.lane === name),
  };
}

/**
 * The component side: runs the schedule and applies `timing`, once per
 * change of its inputs. `length` is the scene length the schedule fits into,
 * in the same frames the component counts.
 */
function useTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
  props: Props,
  length: number,
  timing?: Timing<Id>,
): ResolvedTimeline<Id> {
  return useMemo(
    () => resolve(schedule(props, { length }), timing),
    [schedule, props, length, timing],
  );
}

// Each letter's dot arriving, a breath rippling across the dots, and each
// dot opening into its letter. Frames on the 30 fps scene timeline, after
// `delay` and `speed`. The ids are public: a saved `timing` prop refers to
// them.

type UnmaskLineElementId =
  | `dot:${number}`
  | "breath"
  | `letter:${number}`;

interface UnmaskLineTimingProps {
  lines?: string[];
  openAt?: number;
  stagger?: number;
}

const DEFAULT_LINES = ["Out of", "stealth."];
/** Dots arrive `DOT_GAP` apart over `DOT_LEN`; each line `LINE_LAG` later. */
const DOT_GAP = 1.2;
const DOT_LEN = 10;
const LINE_LAG = 4;
/** The breath swells each dot over `BREATH_LEN`, `BREATH_GAP` apart. */
const BREATH_AT = 18;
const BREATH_GAP = 1.4;
const BREATH_LEN = 12;
/** A dot opens into its letter over `OPEN_LEN`. */
const OPEN_AT = 38;
const OPEN_GAP = 2.2;
const OPEN_LEN = 12;

/** The lines drawn, one blank line when there are none. */
function linesOf(lines: string[]) {
  return lines.length > 0 ? lines : [" "];
}

// `<i>` counts the letters across all lines, spaces skipped. The dots and the
// letters are chains; the breath is one element, the dots swelling `gap`
// apart for `pulse` frames each.
const unmaskLineTimeline = defineTimeline<
  UnmaskLineElementId,
  UnmaskLineTimingProps
>(({ lines = DEFAULT_LINES, openAt = OPEN_AT, stagger = OPEN_GAP }) => {
  const letters: { ch: string; li: number }[] = [];
  linesOf(lines).forEach((line, li) => {
    for (const ch of Array.from(line)) {
      if (ch !== " ") letters.push({ ch, li });
    }
  });
  const elements: TimelineElement<UnmaskLineElementId>[] = [];
  letters.forEach(({ ch, li }, i) => {
    elements.push({
      id: `dot:${i}`,
      lane: "Dots",
      label: ch,
      start: li * LINE_LAG + i * DOT_GAP,
      length: DOT_LEN,
      follows: i > 0 ? `dot:${i - 1}` : undefined,
    });
  });
  elements.push({
    id: "breath",
    lane: "Breath",
    label: "Breath",
    start: BREATH_AT,
    length: Math.max(0, letters.length - 1) * BREATH_GAP + BREATH_LEN,
    beats: { gap: BREATH_GAP, pulse: BREATH_LEN },
  });
  letters.forEach(({ ch }, i) => {
    elements.push({
      id: `letter:${i}`,
      lane: "Letters",
      label: ch,
      start: openAt + i * stagger,
      length: OPEN_LEN,
      follows: i > 0 ? `letter:${i - 1}` : undefined,
    });
  });
  // Stable, so a chain keeps its order on equal starts.
  return elements.sort((a, b) => a.start - b.start);
});

const plex = loadPlexMono("normal", {
  weights: ["500"],
  subsets: ["latin"],
});

interface UnmaskLineProps {
  lines?: string[];
  highlight?: number;
  /** Frame the dots start opening into letters. */
  openAt?: number;
  /** Frames between letters opening. */
  stagger?: number;
  accent?: string;
  /** Text color; overrides the theme ink. */
  ink?: string;
  background?: string;
  /** Typeface for the lines; keep it monospaced so letters sit on the dot grid. Load it yourself; IBM Plex Mono by default. */
  fontFamily?: string;
  /** Size of the lines, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  speed?: number;
  theme?: "dark" | "light";
  /**
   * Moves, trims or stretches single dots arriving, the breath and single
   * letters opening, by the ids in `./timeline`. Frames on the scene
   * timeline, after `delay` and `speed`.
   */
  timing?: Timing<UnmaskLineElementId>;
}

const GREEN = { dark: "#00C805", light: "#00873C" } as const;

const THEMES = {
  dark: { bg: "#000000", ink: "#FFFFFF" },
  light: { bg: "#FFFFFF", ink: "#000000" },
} as const;

const DOT_R = 0.1;
const LEADING = 1.08;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_OPEN = Easing.bezier(0.33, 0, 0.15, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

interface Metrics {
  adv: number;
  cap: number;
  xh: number;
  base: number;
}

function measure(fontFamily: string): Metrics {
  const ctx = document.createElement("canvas").getContext("2d");
  if (!ctx) throw new Error("unmask-line: no 2d context");
  ctx.font = `500 100px "${fontFamily}"`;
  const m = ctx.measureText("HHHHHHHHHH");
  const asc = m.fontBoundingBoxAscent / 100;
  const desc = m.fontBoundingBoxDescent / 100;
  return {
    adv: m.width / 1000,
    cap: m.actualBoundingBoxAscent / 100,
    xh: ctx.measureText("x").actualBoundingBoxAscent / 100,
    base: (1 - (asc + desc)) / 2 + asc,
  };
}

function useMetrics(fontFamily: string) {
  const [m, setM] = useState<Metrics | null>(null);
  const [handle] = useState(() => delayRender("unmask-line: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    Promise.all([
      plex.waitUntilDone(),
      document.fonts.load(`500 100px "${fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setM(measure(fontFamily));
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [fontFamily, handle]);
  return m;
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

function UnmaskLineBase(props: UnmaskLineProps) {
  const {
    lines = DEFAULT_LINES,
    highlight = -1,
    accent,
    ink,
    background,
    fontFamily = plex.fontFamily,
    scale = 1,
    delay = 0,
    speed = 1,
    theme = "dark",
    timing,
  } = props;
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width: W, height: H, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    unmaskLineTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const c = THEMES[theme];
  const green = accent ?? GREEN[theme];
  const fg = ink ?? c.ink;
  const m = useMetrics(fontFamily);

  const transparent = background === "transparent";
  const stage = transparent ? "transparent" : (background ?? c.bg);

  if (!m) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const list = linesOf(lines);
  const breathEl = tl.get("breath");
  const hl = highlight < 0 ? list.length + highlight : highlight;
  const portrait = H > W * 1.1;
  const margin = Math.min(W, H) * (portrait ? 0.08 : 0.09);
  const widest = Math.max(...list.map((l) => Array.from(l).length));
  const F = Math.min(
    (H * (portrait ? 0.4 : 0.66)) / (list.length * LEADING),
    (W - 2 * margin) / Math.max(1, widest * m.adv),
  );
  const lineH = F * LEADING;
  const blockH = lineH * (list.length - 1) + m.cap * F;
  const firstBase = (H - blockH) / 2 + m.cap * F;
  const cell = m.adv * F;

  let order = 0;
  const nodes: React.ReactNode[] = [];
  list.forEach((line, li) => {
    const baseY = firstBase + li * lineH;
    const color = li === hl ? green : fg;
    Array.from(line).forEach((ch, ci) => {
      if (ch === " ") return;
      const i = order++;
      const x = margin + ci * cell;
      const cx = x + cell / 2;
      const cy = baseY - m.xh * F * 0.5;
      const dot = tl.get(`dot:${i}`);
      const letter = tl.get(`letter:${i}`);
      const arrive = interpolate(t, [dot.start, dot.end], [0, 1], {
        ...CLAMP,
        easing: EASE_OUT,
      });
      const pulse = breathEl.beat("pulse");
      const bt = t - (breathEl.start + i * breathEl.beat("gap"));
      const breath =
        bt > 0 && bt < pulse ? Math.sin((bt / pulse) * Math.PI) : 0;
      const p = interpolate(t, [letter.start, letter.end], [0, 1], {
        ...CLAMP,
        easing: EASE_OPEN,
      });
      const r0 = DOT_R * F * (0.5 + 0.5 * arrive) * (1 + 0.22 * breath);
      const rFull = Math.hypot(cell * 0.6, F * 0.8);
      const r = r0 + (rFull - r0) * p;
      const dotOpacity = arrive * interpolate(p, [0, 0.4], [1, 0], CLAMP);
      if (dotOpacity > 0.002) {
        nodes.push(
          <div
            key={`d${li}-${ci}`}
            style={{
              position: "absolute",
              left: cx - r,
              top: cy - r,
              width: r * 2,
              height: r * 2,
              borderRadius: "50%",
              background: color,
              opacity: dotOpacity,
            }}
          />,
        );
      }
      if (p > 0) {
        const top = baseY - m.base * F;
        nodes.push(
          <div
            key={`g${li}-${ci}`}
            style={{
              position: "absolute",
              left: x,
              top,
              height: F,
              lineHeight: `${F}px`,
              fontFamily,
              fontWeight: 500,
              fontSize: F,
              whiteSpace: "pre",
              color,
              clipPath:
                p >= 0.999
                  ? undefined
                  : `circle(${r.toFixed(2)}px at ${(cx - x).toFixed(2)}px ${(cy - top).toFixed(2)}px)`,
            }}
          >
            {ch}
          </div>,
        );
      }
    });
  });

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <ScaleLayer scale={scale}>{nodes}</ScaleLayer>
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  highlight: {
    type: "number",
    default: -1,
    min: -10,
    max: 10,
    step: 1,
    description: "Highlight",
    hiddenFromList: false,
  },
  openAt: {
    type: "number",
    default: 38,
    min: 10,
    max: 90,
    step: 1,
    description: "Open at (frame)",
    hiddenFromList: false,
  },
  stagger: {
    type: "number",
    default: 2.2,
    min: 0,
    max: 8,
    step: 0.2,
    description: "Letter stagger",
    hiddenFromList: false,
  },
  accent: {
    type: "color",
    default: undefined,
    description: "Accent",
  },
  fontFamily: {
    type: "font-family",
    default: "IBM Plex Mono",
    description: "Font",
  },
  ink: {
    type: "color",
    default: undefined,
    description: "Text color",
  },
  background: {
    type: "color",
    default: undefined,
    description: "Background",
  },
  scale: {
    type: "number",
    default: 1,
    min: 0.5,
    max: 1.5,
    step: 0.05,
    description: "Scale",
    hiddenFromList: false,
  },
  delay: {
    type: "number",
    default: 0,
    min: 0,
    max: 60,
    step: 1,
    description: "Delay (frames)",
    hiddenFromList: false,
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","highlight","openAt","stagger","accent","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  highlight: -1,
  openAt: 38,
  stagger: 2.2,
  fontFamily: "IBM Plex Mono",
  scale: 1,
  delay: 0,
  speed: 1,
};

type UnmaskLineElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof UnmaskLineBase>;

const UnmaskLineInner = forwardRef<
  HTMLDivElement,
  UnmaskLineElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<UnmaskLine>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <UnmaskLineBase
          {...(componentProps as unknown as ComponentProps<typeof UnmaskLineBase>)}
        />
      </div>
    </Sequence>
  );
});

export const UnmaskLine = Interactive.withSchema({
  Component: UnmaskLineInner,
  componentName: "<UnmaskLine>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
